public sealed class CsvOrderConverter : JsonConverter<Order> {   // one per layout
    public override Order Read(ref Utf8JsonReader r, Type t, JsonSerializerOptions o) {
        using var doc = JsonDocument.ParseValue(ref r);
        return CsvOrder.ToCanonical(doc.RootElement.GetString()!);   // mapping is yours
    }
    public override void Write(Utf8JsonWriter w, Order v, JsonSerializerOptions o) { /* ... */ }
}

var options = new JsonSerializerOptions();
options.Converters.Add(new CsvOrderConverter());        // the registry
var order = JsonSerializer.Deserialize<Order>(raw, options);   // routing by the library

